local CostumeTailor = {}
local PRODUCTS = {
    simple_linen_costume = { name = "Preprost laneni kostum", linenCost = 3, threadCost = 1, time = 4, cost = 50, artistry = 18, happiness = 2, description = "Preprost laneni kostum za gledališče." },
    painted_silk_costume = { name = "Poslikani svileni kostum", silkCost = 2, linenCost = 1, threadCost = 1, paintCost = 1, time = 7, cost = 140, artistry = 35, happiness = 2, prestige = 2, description = "Poslikani svileni kostum za trgovce." },
    velvet_noble_costume = { name = "Žamčasti plemiški kostum", silkCost = 3, linenCost = 1, threadCost = 1, leatherCost = 1, paintCost = 1, time = 10, cost = 340, artistry = 50, happiness = 3, prestige = 6, description = "Žamčasti plemiški kostum za plemiče." },
    silver_trimmed_costume = { name = "Srebrnoobrobljeni kostum", silkCost = 3, silverCost = 1, linenCost = 1, leatherCost = 1, threadCost = 1, paintCost = 1, time = 14, cost = 800, artistry = 65, happiness = 4, prestige = 14, description = "Srebrnoobrobljeni kostum za visoke plemiče." },
    gold_embroidered_costume = { name = "Zlato vezen kostum", silkCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, threadCost = 1, paintCost = 1, jewelCost = 1, time = 18, cost = 1800, artistry = 78, happiness = 6, prestige = 27, description = "Zlato vezen kostum z draguljem za visoko plemstvo." },
    royal_grand_costume = { name = "Kraljevski veliki kostum", silkCost = 6, goldCost = 2, silverCost = 2, leatherCost = 1, threadCost = 2, paintCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 4100, artistry = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski kostum z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    costume_workshop = { name = "Kostumna delavnica", cost = { gold = 240, wood = 120, stone = 100, silk = 6, thread = 6 }, upkeep = 5, qualityBonus = 5 },
    wardrobe_loft = { name = "Garderobna podstrešje", cost = { gold = 880, wood = 260, stone = 240, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_costumier_atelier = { name = "Mojstrski kostumerski atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_wardrobe_palace = { name = "Kraljevska garderobna palača", cost = { gold = 10000, wood = 580, stone = 740, gold = 65, jewel = 16 }, upkeep = 200, qualityBonus = 55, prestigeBonus = 50 },
}
CostumeTailor.silkStock = 14; CostumeTailor.linenStock = 12; CostumeTailor.threadStock = 12; CostumeTailor.leatherStock = 10; CostumeTailor.paintStock = 10; CostumeTailor.silverStock = 6; CostumeTailor.goldStock = 6; CostumeTailor.jewelStock = 4; CostumeTailor.pearlStock = 4
CostumeTailor.productStock = {}; CostumeTailor.buildings = {}; CostumeTailor.maker = nil; CostumeTailor.activeMaking = {}; CostumeTailor.totalProducts = 0; CostumeTailor.dayTimer = 0
function CostumeTailor.init() CostumeTailor.silkStock=14; CostumeTailor.linenStock=12; CostumeTailor.threadStock=12; CostumeTailor.leatherStock=10; CostumeTailor.paintStock=10; CostumeTailor.silverStock=6; CostumeTailor.goldStock=6; CostumeTailor.jewelStock=4; CostumeTailor.pearlStock=4; CostumeTailor.productStock={}; CostumeTailor.buildings={}; CostumeTailor.maker=nil; CostumeTailor.activeMaking={}; CostumeTailor.totalProducts=0; CostumeTailor.dayTimer=0; print("[CostumeTailor] Royal Costume Tailor System initialized (6 products, 4 buildings)") end
function CostumeTailor.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CostumeTailor.maker={name=n or ("Kostumar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kostumar najet: %s (spretnost: %d)",CostumeTailor.maker.name,s),"success") end; return true end
function CostumeTailor.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CostumeTailor.build(id) local ok,e=CostumeTailor.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CostumeTailor.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CostumeTailor.getQualityBonus() local b=0; for _,bd in ipairs(CostumeTailor.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CostumeTailor.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and CostumeTailor.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.linenCost and CostumeTailor.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.threadCost and CostumeTailor.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.leatherCost and CostumeTailor.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.paintCost and CostumeTailor.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and CostumeTailor.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CostumeTailor.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CostumeTailor.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CostumeTailor.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CostumeTailor.buildings==0 then return false,"Potrebna kostumna delavnica" end; if not CostumeTailor.maker then return false,"Potreben kostumar" end; return true end
function CostumeTailor.make(pt,qty) qty=qty or 1; local ok,e=CostumeTailor.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then CostumeTailor.silkStock=CostumeTailor.silkStock-d.silkCost*qty end; if d.linenCost then CostumeTailor.linenStock=CostumeTailor.linenStock-d.linenCost*qty end; if d.threadCost then CostumeTailor.threadStock=CostumeTailor.threadStock-d.threadCost*qty end; if d.leatherCost then CostumeTailor.leatherStock=CostumeTailor.leatherStock-d.leatherCost*qty end; if d.paintCost then CostumeTailor.paintStock=CostumeTailor.paintStock-d.paintCost*qty end; if d.silverCost then CostumeTailor.silverStock=CostumeTailor.silverStock-d.silverCost*qty end; if d.goldCost then CostumeTailor.goldStock=CostumeTailor.goldStock-d.goldCost*qty end; if d.jewelCost then CostumeTailor.jewelStock=CostumeTailor.jewelStock-d.jewelCost*qty end; if d.pearlCost then CostumeTailor.pearlStock=CostumeTailor.pearlStock-d.pearlCost*qty end; local t=d.time; if CostumeTailor.maker then t=math.max(1,t-math.floor(CostumeTailor.maker.skill/13)) end; table.insert(CostumeTailor.activeMaking,{id="costume_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Šivanje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CostumeTailor.completeMaking(m) local q=1.0+(CostumeTailor.getQualityBonus()/100); if CostumeTailor.maker then q=q+(CostumeTailor.maker.skill/150) end; q=math.min(2.4,q); CostumeTailor.productStock[m.productType]=(CostumeTailor.productStock[m.productType] or 0)+m.quantity; CostumeTailor.totalProducts=CostumeTailor.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CostumeTailor.maker then CostumeTailor.maker.itemsMade=CostumeTailor.maker.itemsMade+m.quantity; if math.random()<0.25 then CostumeTailor.maker.skill=math.min(100,CostumeTailor.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kostum izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"costume.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function CostumeTailor.update(dt) if not _G.state then return end; CostumeTailor.dayTimer=CostumeTailor.dayTimer+dt; if CostumeTailor.dayTimer>=30 then CostumeTailor.dayTimer=0; for i=#CostumeTailor.activeMaking,1,-1 do local m=CostumeTailor.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CostumeTailor.completeMaking(m); table.remove(CostumeTailor.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CostumeTailor.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CostumeTailor.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CostumeTailor.getStats() return {silkStock=CostumeTailor.silkStock,linenStock=CostumeTailor.linenStock,threadStock=CostumeTailor.threadStock,leatherStock=CostumeTailor.leatherStock,paintStock=CostumeTailor.paintStock,silverStock=CostumeTailor.silverStock,goldStock=CostumeTailor.goldStock,jewelStock=CostumeTailor.jewelStock,pearlStock=CostumeTailor.pearlStock,productStock=CostumeTailor.productStock,numBuildings=#CostumeTailor.buildings,hasMaker=CostumeTailor.maker~=nil,makerName=CostumeTailor.maker and CostumeTailor.maker.name or "—",makerSkill=CostumeTailor.maker and CostumeTailor.maker.skill or 0,activeMaking=#CostumeTailor.activeMaking,totalProducts=CostumeTailor.totalProducts} end
return CostumeTailor
